    by = {}
    for f, o, n in S:
        by.setdefault(f, []).append((o, n))
    dry = "--dry" in sys.argv
    for f, items in by.items():
        t = open(f, encoding="utf8").read()
        ok = True
        for o, n in items:
            c = t.count(o)
            if c != 1:
                print("SKIP %s: %d x %r" % (os.path.basename(f), c, o[:90])); ok = False
            else:
                t = t.replace(o, n)
        if ok and not dry:
            open(f, "w", encoding="utf8").write(t); print("wrote", os.path.basename(f), len(items))
        elif ok:
            print("ok (dry)", os.path.basename(f), len(items))
